import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Deterministically refine a triangular-lattice seed as a full diameter packing.

    Point zero is fixed at the origin to remove translation.  All remaining
    coordinates are free, allowing the slight symmetry breaking unavailable in
    a threefold-orbit construction.  SLSQP maximizes a common squared lower
    distance bound while every pairwise squared distance is constrained to be
    at most one.
    """
    rt3 = np.sqrt(3.0)
    upper = np.triu_indices(16, 1)

    removed = {(2, 0), (-2, 2), (0, -2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2 and (q, r) not in removed
    ]
    seed = np.array(
        [(q + 0.5 * r, 0.5 * rt3 * r) for q, r in axial],
        dtype=np.float64,
    )
    seed -= seed[0]

    def normalize(points):
        delta = points[:, None, :] - points[None, :, :]
        diameter = np.sqrt(np.max(np.einsum("ijk,ijk->ij", delta, delta)))
        return points / diameter

    def distances2(points):
        delta = points[:, None, :] - points[None, :, :]
        return np.einsum("ijk,ijk->ij", delta, delta)[upper]

    def quality(points):
        d2 = distances2(points)
        return float(np.min(d2) / np.max(d2))

    best = normalize(seed)
    best_quality = quality(best)

    try:
        from scipy.optimize import minimize

        def unpack(v):
            return np.vstack((np.zeros(2), v.reshape(15, 2)))

        def constraints(v):
            d2 = distances2(unpack(v[:-1]))
            return np.concatenate((d2 - v[-1], 1.0 - d2))

        rng = np.random.default_rng(16022026)
        starts = [best[1:].ravel()]
        starts += [
            normalize(
                np.vstack((
                    np.zeros(2),
                    best[1:] + rng.normal(0.0, scale, (15, 2)),
                ))
            )[1:].ravel()
            for scale in (0.003, 0.007, 0.014, 0.025)
            for _ in range(4)
        ]

        for start in starts:
            result = minimize(
                lambda v: -v[-1],
                np.r_[start, best_quality * 0.98],
                method="SLSQP",
                bounds=[(-1.1, 1.1)] * 30 + [(0.0, 1.0)],
                constraints={"type": "ineq", "fun": constraints},
                options={"maxiter": 1800, "ftol": 1e-13, "disp": False},
            )
            candidate = normalize(unpack(result.x[:-1]))
            value = quality(candidate)
            if np.isfinite(value) and value > best_quality:
                best, best_quality = candidate, value
    except Exception:
        pass

    return np.asarray(best, dtype=np.float64)


